<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request } from '../../services/api'
const products=ref([]), cart=ref({}), keyword=ref(''), category=ref('全部'), shopper=ref('demo-01'), orders=ref([]), note=ref(''), loading=ref(true);const cats=['全部','饮品','乳品','食品','零食'];const filtered=computed(()=>products.value.filter(p=>(category.value==='全部'||p.category===category.value)&&(!keyword.value||p.name.includes(keyword.value))));const count=computed(()=>Object.values(cart.value).reduce((a,b)=>a+b,0));const total=computed(()=>products.value.reduce((a,p)=>a+(cart.value[p.id]||0)*p.price,0));
async function load(){try{products.value=await request('/api/products');orders.value=await request(`/api/orders?shopper=${shopper.value}`)}catch(e){note.value=e.message||'服务暂不可用'}finally{loading.value=false}}function add(p){if(!p.stock){note.value='该商品暂时缺货';return}cart.value={...cart.value,[p.id]:Math.min(p.stock,(cart.value[p.id]||0)+1)};uni.setStorageSync('selfshop-cart',cart.value)}function minus(p){cart.value={...cart.value,[p.id]:Math.max(0,(cart.value[p.id]||0)-1)};uni.setStorageSync('selfshop-cart',cart.value)}async function scan(){try{const result=await new Promise((resolve,reject)=>uni.scanCode({success:resolve,fail:reject}));const p=await request(`/api/products/barcode/${encodeURIComponent(result.result)}`);add(p);note.value=`已识别：${p.name}`}catch(e){note.value='扫码演示：可在开发者工具调用扫码，当前先使用商品卡片添加'}}async function checkout(){try{const items=Object.entries(cart.value).filter(([,q])=>q>0).map(([productId,quantity])=>({productId:Number(productId),quantity}));if(!items.length)throw Error('购物袋还是空的');const result=await request('/api/orders','POST',{shopper:shopper.value,items});orders.value=[result,...orders.value];cart.value={};uni.setStorageSync('selfshop-cart',cart.value);note.value=`结算成功，订单 #${result.id} 已创建（待支付演示）`;uni.showToast({title:'结算成功',icon:'success'})}catch(e){note.value=e.message||'结算失败'}}onLoad(()=>{cart.value=uni.getStorageSync('selfshop-cart')||{};load()})
</script>
<template><view class="page"><view class="hero"><view><text class="eyebrow">SELF CHECKOUT · SMART STORE</text><text class="title">拿了就走，轻松结算</text><text class="subtitle">扫码识别 · 库存校验 · 自助下单</text></view><text class="hero-icon">🛒</text></view><view class="search"><input v-model="keyword" placeholder="搜索商品名称"/><button @click="scan">⌁ 扫码</button></view><scroll-view scroll-x class="cats"><text v-for="c in cats" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</text></scroll-view><view v-if="loading" class="empty">正在加载商品...</view><view v-else class="grid"><view v-for="p in filtered" :key="p.id" class="product"><view class="visual">{{p.icon}}<text v-if="p.badge" class="badge">{{p.badge}}</text><text v-if="p.stock<10" class="stock">仅剩{{p.stock}}件</text></view><text class="category">{{p.category}}</text><text class="name">{{p.name}}</text><text class="price">¥{{p.price}}</text><view class="product-bottom"><text class="carted">{{cart[p.id]?'已选 '+cart[p.id]+' 件':''}}</text><view class="stepper" v-if="cart[p.id]"><button @click="minus(p)">−</button><text>{{cart[p.id]}}</text><button @click="add(p)">＋</button></view><button v-else class="add" @click="add(p)">加入</button></view></view></view><view class="order-section"><view class="section-head"><text class="section-title">我的订单</text><text class="section-tip">自助结算记录</text></view><view v-for="o in orders" :key="o.id" class="order"><view><text class="order-id">订单 #{{o.id}} · ¥{{o.total}}</text><text class="order-detail">{{o.items.map(x=>x.name+'×'+x.quantity).join('、')}}</text></view><text class="status">{{o.status}}</text></view><view v-if="!orders.length" class="empty small-empty">暂无订单</view></view><view class="bottom"><view><text class="count">{{count}} 件</text><text class="total">¥{{total}}</text></view><button @click="checkout" :disabled="!count">立即结算</button></view><view v-if="note" class="toast">{{note}}</view></view></template>
<style scoped>.page{min-height:100vh;background:#f6f7f3;padding-bottom:150rpx}.hero{padding:46rpx 28rpx;background:linear-gradient(135deg,#27463e,#76a393);color:#fff;display:flex;justify-content:space-between;align-items:center}.eyebrow{display:block;font-size:19rpx;letter-spacing:2rpx;opacity:.75}.title{display:block;font-size:45rpx;font-weight:bold;margin-top:20rpx}.subtitle{display:block;font-size:23rpx;opacity:.84;margin-top:12rpx}.hero-icon{font-size:100rpx}.search{display:flex;gap:12rpx;background:#fff;padding:18rpx 22rpx}.search input{flex:1;background:#f5f7f4;height:68rpx;padding:0 18rpx;font-size:23rpx}.search button{background:#27463e;color:#fff;height:68rpx;line-height:68rpx;font-size:22rpx}.cats{background:#fff;height:80rpx;white-space:nowrap}.cats text{display:inline-flex;height:80rpx;align-items:center;padding:0 27rpx;color:#777;font-size:24rpx}.cats text.active{color:#27463e;font-weight:bold;border-bottom:4rpx solid #27463e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx;padding:20rpx}.product{background:#fff;padding-bottom:18rpx}.visual{height:230rpx;background:#e2eee7;display:flex;align-items:center;justify-content:center;font-size:100rpx;position:relative}.product:nth-child(2n) .visual{background:#efe5d5}.badge{position:absolute;left:10rpx;top:10rpx;background:#27463e;color:#fff;padding:5rpx 10rpx;font-size:18rpx}.stock{position:absolute;right:10rpx;bottom:10rpx;color:#9e4937;background:#fff;padding:4rpx 8rpx;font-size:17rpx}.category,.name,.price,.carted{display:block;padding:0 16rpx}.category{color:#9aa59e;font-size:18rpx;margin-top:12rpx}.name{font-size:26rpx;font-weight:bold;margin-top:8rpx}.price{color:#bd5e43;font-size:29rpx;font-weight:bold;margin-top:12rpx}.product-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:14rpx}.carted{font-size:18rpx;color:#89958d}.add{height:52rpx;line-height:52rpx;background:#27463e;color:#fff;font-size:20rpx;margin-right:16rpx}.stepper{display:flex;align-items:center;gap:7rpx;margin-right:12rpx}.stepper button{width:44rpx;height:44rpx;padding:0;line-height:40rpx}.stepper text{font-size:20rpx}.order-section{padding:0 20rpx}.section-head{display:flex;justify-content:space-between;align-items:center;margin:20rpx 0}.section-title{font-size:30rpx;font-weight:bold}.section-tip{font-size:20rpx;color:#999}.order{background:#fff;padding:20rpx;display:flex;justify-content:space-between;border-bottom:1rpx solid #f1f2ef}.order-id,.order-detail{display:block}.order-id{font-weight:bold;font-size:22rpx}.order-detail{color:#999;font-size:19rpx;margin-top:10rpx;max-width:500rpx}.status{font-size:19rpx;color:#9d523e}.empty{text-align:center;padding:45rpx;color:#999}.small-empty{background:#fff}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;padding:14rpx 22rpx;border-top:1rpx solid #eee;display:flex;justify-content:space-between;align-items:center;z-index:5}.count,.total{display:block}.count{font-size:18rpx;color:#999}.total{font-size:31rpx;color:#bd5e43;font-weight:bold}.bottom button{background:#27463e;color:#fff;border:0;height:72rpx;line-height:72rpx;padding:0 30rpx}.bottom button[disabled]{opacity:.45}.toast{position:fixed;bottom:112rpx;left:20rpx;right:20rpx;background:#253c33;color:#fff;padding:20rpx;text-align:center;font-size:21rpx;z-index:7}</style>
